from datetime import date
from decimal import Decimal, ROUND_HALF_UP
import re


_LEGACY_DATE_RE = re.compile(r"\d{8}\Z")
_ISO_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}\Z")


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format, preserving null semantics."""
    if yyyymmdd is None or yyyymmdd in ("", "00000000"):
        return None

    if not isinstance(yyyymmdd, str) or not _LEGACY_DATE_RE.fullmatch(yyyymmdd):
        raise ValueError("legacy date must use YYYYMMDD format")

    parsed = date(
        int(yyyymmdd[0:4]),
        int(yyyymmdd[4:6]),
        int(yyyymmdd[6:8]),
    )
    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO date to legacy YYYYMMDD format and its null sentinel."""
    if iso is None or iso == "":
        return "00000000"

    if not isinstance(iso, str) or not _ISO_DATE_RE.fullmatch(iso):
        raise ValueError("ISO date must use YYYY-MM-DD format")

    parsed = date.fromisoformat(iso)
    return f"{parsed.year:04d}{parsed.month:02d}{parsed.day:02d}"


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N flag to bool; blank and null mean false."""
    if char == "Y":
        return True
    if char in ("N", "", None):
        return False
    raise ValueError("legacy boolean must be 'Y', 'N', blank, or None")


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy amount to currency minor units using half-up rounding."""
    if amount is None or amount == "":
        decimal_amount = Decimal(0)
    else:
        decimal_amount = Decimal(str(amount))

    effective_currency = "USD" if currency is None or currency == "" else currency
    exponent = 0 if effective_currency == "JPY" else 2
    scaled = decimal_amount * (Decimal(10) ** exponent)

    return int(scaled.to_integral_value(rounding=ROUND_HALF_UP))
